func collect(ctx context.Context, srcs []Source) []Item {
	out := make(chan Item, 8)

	for _, src := range srcs {
		go func(s Source) {
			defer close(out) // signal we are done
			for {
				it, ok := s.Next()
				if !ok {
					return
				}
				out <- it
			}
		}(src)
	}

	var all []Item
	for it := range out {
		all = append(all, it)
	}
	return all
}
